import re
import csv
import os

# Create the output directory if it doesn't exist
os.makedirs("results", exist_ok=True)

# Path to the experiment 2 log file (generated by shell script)
log_file = "results/experiment2_summary.log"

# Path to the output CSV file
csv_file = "results/experiment2_data.csv"

# Read all lines from the log file
with open(log_file, "r") as f:
    lines = f.readlines()

# Container to hold parsed records
results = []
current = {}

# Iterate through each line to extract data
for line in lines:
    if line.startswith("[bench="):
        # Start of a new experiment entry: extract metadata like bench, call, and run
        current = {}
        parts = re.findall(r'(\w+)=([-\w\d]+)', line)
        for k, v in parts:
            current[k] = v

    elif "Build Time" in line:
        # Extract build time value from the line and store it
        current["build_time"] = float(re.search(r"([\d.]+)", line).group(1))

    elif "Execution Time" in line:
        # Extract execution time, store current result, and push it to the results list
        current["exec_time"] = float(re.search(r"([\d.]+)", line).group(1))
        results.append(current)

# Write the collected records into a CSV file
with open(csv_file, "w", newline="") as f:
    writer = csv.DictWriter(f, fieldnames=["bench", "call", "run", "build_time", "exec_time"])
    writer.writeheader()
    for r in results:
        writer.writerow(r)
